216	static ssize_t devurand_write(FAR struct file *filep, FAR const char *buffer,
217	                              size_t len)
218	{
219	  /* Write can be used to re-seed the PRNG state. */
220	
221	#ifdef CONFIG_DEV_URANDOM_CONGRUENTIAL
222	  unsigned int seed = 0;
223	
224	  len = MIN(len, sizeof(unsigned int));
225	  memcpy(&seed, buffer, len);
226	  srand(seed);
227	  return len;
228	
229	#elif defined(CONFIG_DEV_URANDOM_RANDOM_POOL)
230	  const unsigned int alignmask = sizeof(uint32_t) - 1;
231	  const size_t initlen = len;
232	  uint32_t tmp = 0;
233	  size_t currlen;
234	
235	  if (!len)
236	    {
237	      return 0;
238	    }
239	
240	  /* Seed entropy pool with data from user. */
241	
242	  if ((uintptr_t)buffer & alignmask)
243	    {
244	      /* Make unaligned input aligned. */
245	
246	      currlen = MIN(sizeof(uint32_t) - ((uintptr_t)buffer & alignmask), len);
247	      memcpy(&tmp, buffer, currlen);
248	      up_rngaddint(RND_SRC_SW, tmp);
249	
250	      len -= currlen;
251	      buffer += currlen;
252	    }
253	
254	  if (len >= sizeof(uint32_t))
255	    {
256	      /* Handle bulk aligned, word-sized data. */
257	
258	      DEBUGASSERT(((uintptr_t)buffer & alignmask) == 0);
259	      currlen = len / sizeof(uint32_t);
260	      up_rngaddentropy(RND_SRC_SW, (FAR uint32_t *)buffer, currlen);
261	      buffer += currlen * sizeof(uint32_t);
262	      len %= sizeof(uint32_t);
263	    }
264	
265	  if (len > 0)
266	    {
267	      /* Handle trailing bytes. */
268	
269	      DEBUGASSERT(len < sizeof(uint32_t));
270	      memcpy(&tmp, buffer, len);
271	      up_rngaddint(RND_SRC_SW, tmp);
272	    }
273	
274	  /* Reseeding of random number generator from entropy pool. */
275	
276	  up_rngreseed();
277	
278	  return initlen;
279	#else
280	  len = MIN(len, sizeof(g_prng.u));
