87	/* First order congruential generators */
88	
89	static inline unsigned long fgenerate1(FAR unsigned long *seed)
90	{
91	  unsigned long randint;
92	
93	  /* First order congruential generator.  One may be added to the result of
94	   * the generated value to avoid the value zero.  This would be fatal for
95	   * the first order random number generator.
96	   */
97	
98	  randint = (RND1_CONSTK * (*seed)) % RND1_CONSTP;
99	  *seed   = (randint == 0 ? 1 : randint);
100	  return randint;
101	}
102	
103	#if (CONFIG_LIBC_RAND_ORDER == 1)
104	static float_t frand1(FAR unsigned long *seed)
105	{
106	  /* First order congruential generator. */
107	
108	  unsigned long randint = fgenerate1(seed);
109	
110	  /* Construct an floating point value in the range from 0.0 up to 1.0 */
111	
112	  return ((float_t)randint) / ((float_t)RND1_CONSTP);
113	}
114	#endif
115	
116	/* Second order congruential generators */
117	
118	#if (CONFIG_LIBC_RAND_ORDER > 1)
119	static inline unsigned long fgenerate2(void)
120	{
121	  FAR struct task_info_s *info = task_get_info();
122	  unsigned long randint;
123	
124	  /* Second order congruential generator. */
125	
126	  randint    = (RND2_CONSTK1 * info->ta_randint1 +
127	                RND2_CONSTK2 * info->ta_randint2) % RND2_CONSTP;
128	
129	  info->ta_randint2 = info->ta_randint1;
130	  info->ta_randint1 = randint;
131	
132	  /* We cannot permit both values to become zero.  That would be fatal for
133	   * the second order random number generator.
134	   */
135	
136	  if (info->ta_randint2 == 0 && info->ta_randint1 == 0)
137	    {
138	      info->ta_randint2 = 1;
139	    }
140	
141	  return randint;
142	}
143	
