145	static float_t frand2(void)
146	{
147	  /* Second order congruential generator */
148	
149	  unsigned long randint = fgenerate2();
150	
151	  /* Construct an floating point value in the range from 0.0 up to 1.0 */
152	
153	  return ((float_t)randint) / ((float_t)RND2_CONSTP);
154	}
