165	  /* Third order congruential generator. */
166	
167	  randint    = (RND3_CONSTK1 * info->ta_randint1 +
168	                RND3_CONSTK2 * info->ta_randint2 +
169	                RND3_CONSTK2 * info->ta_randint3) % RND3_CONSTP;
170	
171	  info->ta_randint3 = info->ta_randint2;
172	  info->ta_randint2 = info->ta_randint1;
173	  info->ta_randint1 = randint;
174	
175	  /* We cannot permit all three values to become zero.  That would be fatal
176	   * for the third order random number generator.
177	   */
178	
179	  if (info->ta_randint3 == 0 && info->ta_randint2 == 0 &&
180	      info->ta_randint1 == 0)
181	    {
182	      info->ta_randint3 = 1;
183	    }
184	
185	  return randint;
186	}
