static inline uint8_t kasan_random_tag(void)
{
  static uint32_t seed = 0x9e3779b9u;
  uint32_t x = seed;

  /* Simple xorshift32 PRNG.  Keep KASAN tag generation independent of the
   * per-task libc rand() state, which is not yet available when the first
   * allocations happen early in nx_start().
   */

  x ^= x << 13;
  x ^= x >> 17;
  x ^= x << 5;
  seed = x;

  return 1 + (uint8_t)(x % ((1u << (64 - KASAN_TAG_SHIFT)) - 2));
}

